import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { app } from "../src/api/routes.ts";
import { resetUsers } from "../src/auth/users.ts";
import { resetSessions } from "../src/auth/session.ts";

const call = (method: string, path: string, body?: unknown, token?: string) =>
  app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });

beforeEach(() => {
  resetUsers();
  resetSessions();
});

test("signup creates the account and signs the user in", async () => {
  const res = await call("POST", "/api/signup", { email: "Grace@example.com", name: "Grace", password: "naval plasma" });
  assert.equal(res.status, 201);
  const { token, user } = res.body as { token: string; user: { id: string; email: string; name: string } };
  assert.deepEqual(user, { id: user.id, email: "grace@example.com", name: "Grace" });
  const me = await call("GET", "/api/me", undefined, token);
  assert.equal(me.status, 200);
  assert.deepEqual(me.body, user);
});

test("signup reports UserErrors as 400", async () => {
  assert.equal((await call("POST", "/api/signup", { email: "a@b.com", name: "X" })).status, 400);
  assert.equal((await call("POST", "/api/signup", { email: "bad", name: "X", password: "long enough" })).status, 400);
  assert.equal((await call("POST", "/api/signup", { email: "a@b.com", name: "X", password: "short" })).status, 400);
  await call("POST", "/api/signup", { email: "a@b.com", name: "X", password: "long enough" });
  const dup = await call("POST", "/api/signup", { email: "A@B.com", name: "Y", password: "long enough" });
  assert.equal(dup.status, 400);
  assert.match(String((dup.body as { error: string }).error), /already registered/);
});

